        required: true,
      },
      {
        name: 'reason',
        description: 'The reason for the ban.',
        type: 'STRING',
        required: false,
      },
    ],
  },
  execute: async ({ client, interaction }) => {
    const { member, guild } = interaction;

    // Check if the bot has permission to ban members
    if (!member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'I do not have permission to ban members.',
        ephemeral: true,
      });
    }

    // Check if the user to ban is the bot itself
    if (interaction.user.id === client.user.id) {
      return interaction.reply({
        content: 'I cannot ban myself.',
        ephemeral: true,
      });
    }

    // Get the user to ban
    const userToBan = interaction.options.getUser('user');

    // Check if the user to ban is the guild owner
    if (userToBan.id === guild.ownerId) {
      return interaction.reply({
        content: 'I cannot ban the guild owner.',
        ephemeral: true,
      });
    }

    // Get the ban reason
    const banReason = interaction.options.getString('reason') || 'No reason provided';

    try {
      await guild.members.ban(userToBan, { days: 0, reason: banReason });
      return interaction.reply({
        content: `${userToBan.tag} has been banned from ${guild.name} for ${banReason}.`,
      });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: 'An error occurred while banning the user.',
        ephemeral: true,
      });
    }
  },
};

// Load and register the commands and events
events.load(client);
commands.load(client);
commands.register(client);

// Login the client
client.login(process.env.DISCORD_TOKEN);
```

This code defines a Discord.js v14 bot that has a single command, `ban`, which is a slash command. The command handler and event handler are defined using ES6 modules, and the `banCommand` is defined separately for clarity. 

The `load` functions load commands and events from their respective folders, while the `register` function registers the commands to the client once it's ready. The `banCommand` is included as an example of a slash command, but additional commands can be added similarly.

This code also includes error handling for the `ban` command, checking if the bot has permission to ban members, if the user to ban is the bot itself or the guild owner, and logging any errors that occur while banning the user.

Title: High-Quality End-to-End Testing Framework Using Cypress, Docker, and Automated Screenshots

Introduction:

This comprehensive testing framework utilizes Cypress, a powerful end-to-end testing tool, alongside Docker to provide a reliable and scalable environment for executing automated tests. Additionally, this framework leverages Cypress's screenshot capabilities to capture and store screenshots automatically during test execution.

Framework Overview:

1. Environment Setup:
   - Install Docker on the local machine.
   - Create a Cypress project with necessary dependencies, e.g., `cypress`, `cypress-multi-reporters`, `cypress-real-device`, and `cypress-xpath`.
   - Create a Dockerfile in the project directory.

2. Dockerfile:

   ```
   FROM node:14-alpine

   # Install Cypress dependencies
   RUN apk update && apk add --no-cache git

   WORKDIR /app

   COPY package*.json ./

   RUN npm install

   COPY . .

   CMD ["npm", "run", "test"]
   ```

   This Dockerfile uses the official Node.js 14 Alpine image and installs Cypress dependencies. The `COPY` commands copy the project files to the container, and the `CMD` command executes the Cypress test command.

3. Cypress Configuration:

   - Create a `.dockerignore` file to exclude Cypress test assets and `node_modules`.

     ```
     cypress/
     node_modules/
     ```

   - Create a `cypress.json` file to configure Cypress for Docker and device emulation.

     ```
     {
       "chromeWebSecurity": false,
       "reporter": "cypress-multi-reporters",
       "reporterOptions": {
         "reporterEnabled": "mocha-junit-reporter,dist/failedTests.png"
       },
       "viewportPreferred": "retina",
       "viewportSizes": ["1200", "900", "768", "640"],
       "experimentalViewport": true,
       "experimentalDeviceShadow": true,
       "experimentalInteractiveRun": true,
       "experimentalSessionAndContext": true,
       "experimentalViewportRates": true,
       "experimentalVideo": true,
       "video": false,
       "videoCompression": 0,
       "videoUploadOnPasses": false,
       "videoUploadOnFailedSpecs": true,
       "videoUploadOnSessionFailures": true,
       "videoSettings": {
         "destination": "dist/videos",
         "format": "mp4",
         "maxDuration": 300,
         "maxSize": 1024 * 1024,
         "quality": "high",
         "retainDuplicates": false,
         "skipSilentVideos": true,
         "skipVideosWithoutInteractions": true
       },
       "testFiles": "**/*.spec.js",
       "specPattern": "**/*.spec.js",
       "baseUrl": "http://localhost:8080",
       "chrome": {
         "args": [
           "--disable-infobars",
           "--window-size=1200,900",
           "--disable-background-networking",
           "--disable-background-timer-throttling",
           "--disable-backgrounding-occluded-windows",
           "--disable-breakpad",
           "--disable-client-side-phishing-detection",
           "--disable-component-update",
           "--disable-dev-shm-usage",
           "--disable-extensions",
           "--disable-features=site-per-process",
           "--disable-hang-monitor",
           "--disable-popup-blocking",
           "--disable-prompt-on-reposture",
           "--disable-sync",
           "--disable-translate",
           "--metrics-recording-only",
           "--no-first-run",
           "--safebrowsing-disable-auto-update",
           "--enable-automation",
           "--allow-cross-origin-auth-prompt",
           "--start-maximized",
           "--use-mock-keychain",
           "--disable-web-security",
           "--allow-file-access-from-files"
         ]
       }
     }
     ```

   - Create a `cypress/plugins/index.js` file to enable Cypress to run in Docker containers.

     ```
     const { registerDeviceEmulation } = require('cypress-device-emulation');

     module.exports = (on, config) => {
       registerDeviceEmulation(on, config);

       return config;
     };
     ```

   - Create a `cypress/support/index.js` file to add custom commands.

     ```
     import { addFixture } from 'cypress-fixture';

     Cypress.Commands.add('fixture', (fixtureName) => {
       cy.fixture(fixtureName).then((data) => {
         cy.wrap(data);
       });
     });

     Cypress.Commands.add('captureScreenshot', (fileName) => {
       cy.task('saveScreenshot', fileName);
     });

     Cypress.Commands.add('saveScreenshot', (fileName) => {
       cy.log(`Capturing screenshot: ${fileName}.png`);
       cy.context('capture')
         .then((context) => {
           const canvas = context.getCanvas();
           const screenshotBuffer = canvas.toDataURL('image/png').replace('data:image/png;base64,', '');
           const screenshotStream = Buffer.from(screenshotBuffer, 'base64');
           cy.writeFile(`cypress/screenshots/${fileName}.png`, screenshotStream);
         });
     });

     Cypress.Commands.add('loadFixtures', () => {
       addFixture();
     });

     Cypress.Commands.add('loadFixturesFor', (specName) => {
       cy.task('loadFixtures', specName);
     });

     Cypress.Commands.add('loadFixturesTask', (specName) => {
       return (cb) => {
         addFixture(specName, cb);
       };
     });

     Cypress.Commands.add('loadFixtures', (specName) => {
       cy.task('loadFixturesTask', specName)();
     });

     Cypress.Commands.add('loadFixturesForSpec', (specName) => {
       cy.task('loadFixtures', specName);
     });

     Cypress.Commands.add('loadFixturesTaskForSpec', (specName) => {
       return (cb) => {
         addFixture(specName, cb);
       };
     });

     Cypress.Commands.add('loadFixturesForSpecTask', (specName) => {
       return (cb) => {
         cy.task('loadFixturesTask', specName)(cb);
       };
     });

     Cypress.Commands.add('loadFixturesForSpec', (specName) => {
       cy.task('loadFixturesForSpecTask', specName)();
     });
     ```

   - Create a `cypress/plugins/task.js` file to handle fixtures loading.

     ```
     const { addFixture } = require('cypress-fixture');

     module.exports = (task, { spec }) => {
       return (cb) => {
         addFixture(spec, (err) => {
           if (err) {
             console.error(err);
           }
           cb();
         });
       };
     };
     ```

4. Test Execution:

   - Create a `package.json` file with the following scripts:

     ```
     {
       "scripts": {
         "test": "cypress run --spec 'cypress/integration/**/*.spec.js' --reporter mochawesome --reporter-options 'reportDir=dist/reports,reportFilename=result.json'",
         "test:head": "docker run -v $(pwd):/app -w /app --rm -e CI=true cypress/base:14.17.0 node node_modules/cypress/bin/cypress run --spec 'cypress/integration/**/*.spec.js' --reporter mochawesome --reporter-options 'reportDir=dist/reports,reportFilename=result.json'",
         "test:chrome": "docker run -v $(pwd):/app -w /app --rm -e CI=true -e DISPLAY=:0 \
           -v /tmp/.X11-unix:/tmp/.X11-unix \
           cypress/base:14.17.0 node node_modules/cypress/bin/cypress run --spec 'cypress/integration/**/*.spec.js' --reporter mochawesome --reporter-options 'reportDir=dist/reports,reportFilename=result.json'",
         "test:video": "docker run -v $(pwd):/app -w /app --rm -e CI=true cypress/base:14.17.0 node node_modules/cypress/bin/cypress run --spec 'cypress/integration/**/*.spec.js' --record-video-on-failure --video-format mp4 --video-autorotate false --video-name video",
         "test:chrome:real-device": "docker run -v $(pwd):/app -w /app --rm -e CI=true -e DISPLAY=:0 \
           -v /tmp/.X11-unix:/tmp/.X11-unix \
           -e CHROME_BIN=/app/node_modules/cypress/node_modules/puppeteer/.local-chrome/chrome \
           cypress/base:14.17.0 node node_modules/cypress/bin/cypress run --spec 'cypress/integration/**/*.spec.js' --reporter mochawesome --reporter-options 'reportDir=dist/reports,reportFilename=result.json' --spec-pattern 'cypress/integration/**/*.spec.js' --viewportWidth 1200 --viewportHeight 900 --browser 'chrome' --headed --record --key 'captureVideo',false --key 'captureRetinaDisplay',false --key 'captureFullPageScreenshot',true --key 'screenshotOnLastViewport',true --key 'videoCompression',0 --key 'videoUploadOnPasses',false --key 'videoUploadOnFailedSpecs',true --key 'videoUploadOnSessionFailures',true --key 'videoSettings.format',mp4 --key 'videoSettings.quality","high" --key 'videoSettings.retainDuplicates',false --key 'videoSettings.skipSilentVideos',true --key 'videoSettings.skipVideosWithoutInteractions',true --key 'videoSettings.destination',dist/videos --key 'viewportRates/0/rate",1 --key 'viewportRates/0/width',1200 --key 'viewportRates/0/height',900 --key 'viewportRates/1/rate",1 --key 'viewportRates/1/width',900 --key 'viewportRates/1/height',768 --key 'viewportRates/2/rate",1 --key 'viewportRates/2/width',768 --key 'viewportRates/2/height',640 --key 'experimentalViewportRates',true --key 'experimentalViewport',true --key 'experimentalDeviceShadow',true --key 'experimentalInteractiveRun',true --key 'experimentalSessionAndContext',true",
         "test:load-fixtures": "npm run test && npm run load-fixtures-for-spec cypress/integration/**/example.spec.js",
         "load-fixtures-for-all": "npm run load-fixtures-task",
         "load-fixtures-for-spec": "npm run load-fixtures-task-for-spec",
         "load-fixtures-task": "node node_modules/cypress/plugins/task.js loadFixtures --spec 'cypress/integration/**/*.spec.js'",
         "load-fixtures-task-for-spec": "node node_modules/cypress/plugins/task.js loadFixtures --spec 'cypress/integration/$1.spec.js'"
       }
     }
     ```

   - Run tests using the following commands:

     - Run Cypress tests in headless mode:

       ```
       npm run test:head
       ```

     - Run Cypress tests with Chrome browser in headless mode:

       ```
       npm run test:chrome
       ```

     - Run Cypress tests with video recording:

       ```
       npm run test:video
       ```

     - Run Cypress tests with real device emulation:

       ```
       npm run test:chrome:real-device
       ```

     - Load fixtures for all tests:

       ```
       npm run load-fixtures-for-all
       ```

     - Load fixtures for a specific test:

       ```
       npm run load-fixtures-for-spec cypress/integration/**/example.spec.js
       ```

     - Load fixtures for a specific test task:

       ```
       npm run load-fixtures-task-for-spec cypress/integration/**/example.spec.js
       ```

     - Load fixtures for all tests task:

       ```
       npm run load-fixtures-task
       ```

5. Automated Screenshots:

   - In your Cypress tests, use the `captureScreenshot` command to capture a screenshot:

     ```
     it('should take a screenshot', () => {
       cy.visit('http://localhost:8080');
       cy.get('#my-element').should('exist');
       cy.captureScreenshot('my-element');
     });
     ```

6. Test Reports:

   - After running Cypress tests, you can find the test reports in the `dist/reports` folder.

   - To generate JUnit-style XML test reports, update the `reporterOptions` in the `cypress.json` file:

     ```
     "reporterOptions": {
       "reporterEnabled": "mocha-junit-reporter,dist/failedTests.png"
     }
     ```

7. Fixtures:

   - Use the `loadFixtures` command to load fixtures before each test:

     ```
     before(() => {
       cy.loadFixtures();
     });

     it('should use the loaded fixtures', () => {
       // Use the loaded fixtures here
     });
     ```

8. Docker Compose:

   - If you want to use Docker Compose, create a `docker-compose.yml` file:

     ```
     version: '3'

     services:
       cypress:
         build:
           context: .
         volumes:
           - .:/app
           - /tmp/.X11-unix:/tmp/.X11-unix
         environment:
           - DISPLAY=:0
         command: npm run test:chrome:real-device
     ```

   - To run tests using Docker Compose:

     ```
     docker-compose up
     ```

9. Continuous Integration:

   - This framework can be easily integrated with CI tools like Jenkins or Travis CI.

   - Use the `test` script to run Cypress tests.

   - Use the `load-fixtures-for-all` script to load fixtures before each test.

   - Use the `test:video` script to record videos.

   - Use the `test:chrome:real-device` script to run tests on real devices.

10. Conclusion:

   This comprehensive testing framework leverages Cypress, Docker, and automated screenshots to provide a reliable and scalable environment for executing end-to-end tests. Additionally, this framework allows for effortless fixture management, test report generation, and integration with continuous integration tools.

