std::string markdown_to_html(const std::string& markdown_text) {
    // Define regular expressions and replacement strings for common Markdown syntax
    std::string html_text;

    // Headers
    std::regex header_regex("^#{1,6}(.*)\\s?$");
    std::string header_open = "<h";
    std::string header_close = ">";
    std::string header_level;
    std::smatch header_match;
    while (std::regex_search(markdown_text, header_match, header_regex)) {
        header_level = std::to_string(header_match.size()) + ">";
        html_text += header_open + header_level + header_close + header_match[1] + "</h" + header_level + ">\n";
        markdown_text = header_match.suffix().str();
    }

    // Bold and italic
    std::regex bold_regex("\\*([^*]+)\\*");
    std::regex italic_regex("\\_([^_]+)\\_");
    std::string bold_open = "<strong>";
    std::string bold_close = "</strong>";
    std::string italic_open = "<em>";
    std::string italic_close = "</em>";
    while (std::regex_search(markdown_text, bold_regex)) {
        html_text += bold_open + std::regex_replace(std::regex_match(markdown_text, bold_regex), bold_regex, "$1") + bold_close + "\n";
        markdown_text = std::regex_replace(markdown_text, bold_regex, "$1");
    }
    while (std::regex_search(markdown_text, italic_regex)) {
        html_text += italic_open + std::regex_replace(std::regex_match(markdown_text, italic_regex), italic_regex, "$1") + italic_close + "\n";
        markdown_text = std::regex_replace(markdown_text, italic_regex, "$1");
    }

    // Links
    std::regex link_regex("\\[([^\\]]+)\\]\\\\(([^\\)]+)\\)");
    std::string link_open = "<a href=\"";
    std::string link_close = "</a>";
    while (std::regex_search(markdown_text, link_regex)) {
        html_text += link_open + std::regex_replace(std::regex_match(markdown_text, link_regex), link_regex, "$2") + ">" + std::regex_replace(std::regex_match(markdown_text, link_regex), link_regex, "$1") + link_close + "\n";
        markdown_text = std::regex_replace(markdown_text, link_regex, "$1 [$1]( $2 )");
    }

    // Lists
    std::regex list_item_regex("^\\s*(?:\\d+\\.\\s+|\\-*\\s+|[\\+]\\s+|[\\] \\s+|\\(\\s+)[^\\n]*)");
    std::string list_open = "<ul>";
    std::string list_close = "</ul>";
    std::string list_item_open = "<li>";
    std::string list_item_close = "</li>";
    std::string list_indent;
    std::string list_text;
    std::vector<std::string> list_items;
    while (std::regex_search(markdown_text, list_item_regex)) {
        list_text = std::regex_replace(std::regex_match(markdown_text, list_item_regex), list_item_regex, "$1");
        list_indent = std::regex_replace(std::regex_match(markdown_text, list_item_regex), list_item_regex, "$`");
        list_items.push_back(list_text);
        markdown_text = std::regex_replace(markdown_text, list_item_regex, "");
    }
    if (!list_items.empty()) {
        html_text += list_open + "\n";
        for (const auto& item : list_items) {
            html_text += list_item_open + list_indent + item + list_item_close + "\n";
        }
        html_text += list_close + "\n";
    }

    // Code blocks
    std::regex code_block_regex("^(?: {4}\\|\\s*)?(`{3,}|~{3,})\\s+(.+?)\\s*(?:`{3,}|~{3,})\\s*$");
    std::string code_block_open = "<pre><code>";
    std::string code_block_close = "</code></pre>";
    while (std::regex_search(markdown_text, code_block_regex)) {
        html_text += code_block_open + std::regex_replace(std::regex_match(markdown_text, code_block_regex), code_block_regex, "$2") + code_block_close + "\n";
        markdown_text = std::regex_replace(markdown_text, code_block_regex, "");
    }

    // Blockquotes
    std::regex blockquote_regex("^> (.*)");
    std::string blockquote_open = "<blockquote>";
    std::string blockquote_close = "</blockquote>";
    while (std::regex_search(markdown_text, blockquote_regex)) {
        html_text += blockquote_open + std::regex_replace(std::regex_match(markdown_text, blockquote_regex), blockquote_regex, "$1") + blockquote_close + "\n";
        markdown_text = std::regex_replace(markdown_text, blockquote_regex, "$1");
    }

    // Paragraphs
    std::regex paragraph_regex("(?:^| [\\n\\r])([^\\n\\r]+)(?:[\\n\\r]|$)");
    std::string paragraph_open = "<p>";
    std::string paragraph_close = "</p>";
    while (std::regex_search(markdown_text, paragraph_regex)) {
        html_text += paragraph_open + std::regex_replace(std::regex_match(markdown_text, paragraph_regex), paragraph_regex, "$1") + paragraph_close + "\n";
        markdown_text = std::regex_replace(markdown_text, paragraph_regex, "$1");
    }

    // Strip extra whitespace
    std::regex extra_whitespace_regex("\\s+");
    html_text = std::regex_replace(html_text, extra_whitespace_regex, " ");

    return html_text;
}
```

Note: This implementation is not exhaustive and may not handle all possible Markdown syntax. It's intended as a starting point for further customization and improvement.

